import type {Token} from './token-service.ts';
export function refresh(current:Token,next:Token){return current;}
export function canLogin(attempts:number){return attempts<3;}

export interface Token {value:string;expires:number}
export function expired(token:Token,now:number){return token.expires<=now;}
export function revoke(tokens:Token[],value:string){return tokens.filter(token=>token.value!==value);}

export interface User {name:string;password:string}
